$ErrorActionPreference = 'Continue'
$repo = 'C:\Users\Xxkan\HeavenBridgeRepo'
Set-Location $repo
$origin = (git remote get-url origin | Out-String).Trim()
if ($origin -notmatch 'fengie/mhw-mods') { Write-Error "Unexpected origin: $origin"; exit 2 }

$fetchOut = (& git fetch origin '+refs/heads/*:refs/remotes/origin/*' --prune 2>&1 | Out-String).Trim()
if ($LASTEXITCODE -ne 0) { Write-Error "Fetch failed: $fetchOut"; exit 3 }

$baseline = (& git rev-parse origin/main 2>$null | Out-String).Trim()
if(-not $baseline){ Write-Error 'origin/main unavailable after explicit fetch'; exit 4 }
$current = (& git branch --show-current | Out-String).Trim()
$worktreeText = (& git worktree list --porcelain | Out-String).Trim()
$worktreeBranches = @()
foreach($line in ($worktreeText -split "[\r\n]+")) {
  if($line -like 'branch refs/heads/*') { $worktreeBranches += ($line -replace '^branch refs/heads/','') }
}

$openPrBranches = @()
if (Get-Command gh -ErrorAction SilentlyContinue) {
  try {
    $j = gh pr list --repo fengie/mhw-mods --state open --limit 200 --json headRefName 2>$null
    if($LASTEXITCODE -eq 0 -and $j) { $openPrBranches = @((ConvertFrom-Json $j) | ForEach-Object {$_.headRefName}) }
  } catch {}
}

$rows = @()
$refs = & git for-each-ref --format='%(refname:short)|%(objectname)|%(committerdate:iso8601)|%(authorname)' refs/heads/ refs/remotes/origin/
foreach($line in $refs){
  if(-not $line){continue}
  $p=$line -split '\|',4
  $full=$p[0]; $sha=$p[1]; $date=$p[2]; $author=$p[3]
  if($full -eq 'origin/HEAD'){continue}
  $scope=if($full.StartsWith('origin/')){'remote'}else{'local'}
  $name=if($scope -eq 'remote'){$full.Substring(7)}else{$full}
  if($name -eq 'main'){
    $rows += [ordered]@{scope=$scope;name=$name;sha=$sha;date=$date;author=$author;baseline=$true}
    continue
  }
  $ancestor=$false
  & git merge-base --is-ancestor $full origin/main 2>$null
  if($LASTEXITCODE -eq 0){$ancestor=$true}
  $treeEqual=$false
  & git diff --quiet origin/main $full 2>$null
  if($LASTEXITCODE -eq 0){$treeEqual=$true}
  $plus=0;$minus=0
  if(-not $ancestor -and -not $treeEqual){
    $ch=@(& git cherry origin/main $full 2>$null)
    $plus=@($ch | Where-Object {$_ -like '+ *'}).Count
    $minus=@($ch | Where-Object {$_ -like '- *'}).Count
  }
  $ab=(& git rev-list --left-right --count "origin/main...$full" 2>$null | Out-String).Trim()
  $proof=if($ancestor){'ancestor-of-main'}elseif($treeEqual){'tree-equal-main'}elseif($plus -eq 0 -and $minus -gt 0){'patch-equivalent-to-main'}else{''}
  $rows += [ordered]@{
    scope=$scope;name=$name;sha=$sha;date=$date;author=$author;aheadBehind=$ab;
    ancestorOfMain=$ancestor;treeEqualMain=$treeEqual;cherryPlus=$plus;cherryMinus=$minus;
    safeProof=$proof;inWorktree=($worktreeBranches -contains $name);
    openPR=($openPrBranches -contains $name);
    special=($name -eq 'heaven-bridge' -or $name -eq 'main' -or $name -like 'release/*')
  }
}
[ordered]@{
  repo=$repo;origin=$origin;fetch=$fetchOut;baseline=$baseline;current=$current;
  worktreeBranches=$worktreeBranches;openPrBranches=$openPrBranches;rows=$rows
} | ConvertTo-Json -Depth 7
